<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\InventoryLocation;use App\Models\ProductVariant;use App\Services\PosService;use Illuminate\Http\Request;
class PosController extends Controller{public function index(){return view('admin.pos.index',['locations'=>InventoryLocation::where('is_active',true)->get()]);}public function search(Request $r){$q=$r->validate(['q'=>'required|string|max:100'])['q'];return ProductVariant::with('product')->where('is_active',true)->where(fn($x)=>$x->where('sku','like',"%$q%")->orWhere('barcode',$q)->orWhereHas('product',fn($p)=>$p->where('name','like',"%$q%")))->limit(20)->get();}public function store(Request $r,PosService $s){$d=$r->validate(['inventory_location_id'=>'required|exists:inventory_locations,id','payment_method'=>'required|in:cash,card,bkash,nagad','paid_amount'=>'required|numeric|min:0','discount_total'=>'nullable|numeric|min:0','items'=>'required|array|min:1','items.*.variant_id'=>'required|exists:product_variants,id','items.*.quantity'=>'required|numeric|min:0.01']);$sale=$s->sell($d,$r->user()->id);return redirect()->route('admin.pos.receipt',$sale);}public function receipt(\App\Models\PosSale $sale){return view('admin.pos.receipt',compact('sale'));}}
